contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // We are the deployer of C (the owner). Take target and amount as inputs and send them via c.sendMoney.
    function run(address target, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        // observe before state
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the owner-only sendMoney call; it must be a top-level statement
        bool reverted;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // If sendMoney succeeded then exactly amount left C and depositsCount unchanged; if it reverted then nothing observable changed.
        assert(reverted ? (afterCount == beforeCount && afterBal == beforeBal) : (afterCount == beforeCount && beforeBal >= amount && afterBal == beforeBal - amount));
    }
    receive() external payable {}
}

